// Meshy API client and the character pipeline's stages (charter "Look": assets are generated by
// a scripted step with a manifest). Pure of process and filesystem concerns so tests can drive
// it with a fake fetch; scripts/assets/character.ts is the CLI around it.

export const MESHY_BASE = "https://api.meshy.ai";

export type TaskStatus = "PENDING" | "IN_PROGRESS" | "SUCCEEDED" | "FAILED" | "CANCELED";

export interface MeshyTask {
  id: string;
  status: TaskStatus;
  progress: number;
  consumed_credits?: number;
  task_error?: { message?: string } | null;
  /** text-to-3d */
  model_urls?: Record<string, string>;
  thumbnail_url?: string;
  /** text-to-image */
  image_urls?: string[];
  finished_at?: number;
  /** rigging and animation */
  result?: Record<string, unknown> | null;
}

/** Where each kind of task lives. */
const ROUTES = {
  textToImage: "/openapi/v1/text-to-image",
  imageTo3d: "/openapi/v1/image-to-3d",
  textTo3d: "/openapi/v2/text-to-3d",
  rigging: "/openapi/v1/rigging",
  animations: "/openapi/v1/animations",
} as const;
export type TaskKind = keyof typeof ROUTES;

export class MeshyError extends Error {
  constructor(
    message: string,
    readonly status: number,
    /** True when retrying the same request cannot help (bad input, auth, credits). */
    readonly permanent: boolean,
  ) {
    super(message);
  }
}

export class Meshy {
  constructor(
    private readonly apiKey: string,
    private readonly fetchFn: typeof fetch = fetch,
    private readonly base = MESHY_BASE,
  ) {
    if (!apiKey) throw new MeshyError("MESHY_API_KEY is not set", 401, true);
  }

  private async call<T>(path: string, init?: RequestInit): Promise<T> {
    const res = await this.fetchFn(`${this.base}${path}`, {
      ...init,
      headers: {
        Authorization: `Bearer ${this.apiKey}`,
        "Content-Type": "application/json",
        ...(init?.headers ?? {}),
      },
    });
    const text = await res.text();
    if (!res.ok) {
      const what =
        res.status === 402
          ? "insufficient Meshy credits"
          : res.status === 401
            ? "Meshy rejected the API key"
            : res.status === 422
              ? "Meshy could not estimate the pose (rigging)"
              : `Meshy HTTP ${res.status}`;
      // Never echo the request (it carries the key in headers, not the body, but be strict).
      const transient = res.status >= 500 || res.status === 429 || res.status === 408;
      throw new MeshyError(`${what}: ${text.slice(0, 300)}`, res.status, !transient);
    }
    return (text ? JSON.parse(text) : {}) as T;
  }

  balance(): Promise<{ balance: number }> {
    return this.call("/openapi/v1/balance");
  }

  /** Submit a task; returns its id. */
  async submit(kind: TaskKind, body: Record<string, unknown>): Promise<string> {
    const r = await this.call<{ result: string }>(ROUTES[kind], {
      method: "POST",
      body: JSON.stringify(body),
    });
    if (!r.result) throw new MeshyError("Meshy returned no task id", 500, false);
    return r.result;
  }

  get(kind: TaskKind, id: string): Promise<MeshyTask> {
    return this.call(`${ROUTES[kind]}/${encodeURIComponent(id)}`);
  }

  /** Poll until the task is terminal. Never resubmits. */
  async wait(
    kind: TaskKind,
    id: string,
    opts: { intervalMs?: number; timeoutMs?: number; onProgress?: (t: MeshyTask) => void } = {},
  ): Promise<MeshyTask> {
    const interval = opts.intervalMs ?? 8000;
    const deadline = Date.now() + (opts.timeoutMs ?? 20 * 60_000);
    for (;;) {
      const t = await this.get(kind, id);
      opts.onProgress?.(t);
      if (t.status === "SUCCEEDED") return t;
      if (t.status === "FAILED" || t.status === "CANCELED")
        throw new MeshyError(
          `${kind} task ${id} ${t.status}: ${t.task_error?.message ?? "no reason given"}`,
          500,
          true,
        );
      if (Date.now() > deadline) throw new MeshyError(`${kind} task ${id} timed out`, 504, false);
      await new Promise((r) => setTimeout(r, interval));
    }
  }
}

// ---- the character pipeline ---------------------------------------------------------------

export interface CharacterSpec {
  form: string;
  /** Concept art prompt: the look is decided here, on a cheap image, before any 3D spend. */
  prompt: string;
  /** Texture prompt for the 3D stage (style, palette). */
  texturePrompt: string;
  heightMeters: number;
  /** In-game look carried into the manifest (see CharacterAsset). */
  selfLight?: number;
  hover?: number;
  /** Clip role -> Meshy animation library action_id. */
  actions: Record<"idle" | "talk" | "react" | "leave", number>;
}

/**
 * concept: text-to-image (inspect it before spending on 3D). model: image-to-3D, textured,
 * remeshed to a game budget. rig: humanoid auto-rig. animate: library clips merged into one GLB.
 */
export type Stage = "concept" | "model" | "rig" | "animate";
export const STAGES: Stage[] = ["concept", "model", "rig", "animate"];

export interface StageTask {
  /** Empty while a submission is in flight (see `submitting`). */
  id: string;
  /**
   * Set before the POST and cleared once the id is saved. Found set on resume, it means a
   * submission may have been accepted without us learning its id: refuse to submit again.
   */
  submitting?: boolean;
  status?: TaskStatus;
  credits?: number | undefined;
  /** Meshy's finished_at (ms), for reproducible manifest dates. */
  finishedAt?: number | undefined;
}

/** What the checkpoint remembers: accepted task ids are never resubmitted. */
export interface Checkpoint {
  form: string;
  tasks: Partial<Record<Stage, StageTask>>;
  /** Downloaded files, relative to the job folder. */
  files: Partial<Record<Stage, string>>;
}

/** Request body for each stage, from the spec and the ids of earlier stages. */
export function stageRequest(
  stage: Stage,
  spec: CharacterSpec,
  cp: Checkpoint,
): { kind: TaskKind; body: Record<string, unknown> } {
  const prev = (s: Stage) => {
    const id = cp.tasks[s]?.id;
    if (!id || cp.tasks[s]?.status !== "SUCCEEDED") throw new Error(`${stage} needs ${s} first`);
    return id;
  };
  switch (stage) {
    case "concept":
      return {
        kind: "textToImage",
        body: {
          ai_model: "nano-banana-2",
          prompt: spec.prompt,
          pose_mode: "a-pose",
          aspect_ratio: "3:4",
          remove_background: true,
        },
      };
    case "model":
      return {
        kind: "imageTo3d",
        body: {
          input_task_id: prev("concept"),
          ai_model: "latest",
          pose_mode: "a-pose",
          should_texture: true,
          enable_pbr: true,
          texture_resolution: "2k",
          texture_prompt: spec.texturePrompt,
          should_remesh: true,
          topology: "triangle",
          target_polycount: 15000,
          target_formats: ["glb"],
        },
      };
    case "rig":
      return {
        kind: "rigging",
        body: { input_task_id: prev("model"), height_meters: spec.heightMeters },
      };
    case "animate":
      return {
        kind: "animations",
        body: { rig_task_id: prev("rig"), action_ids: Object.values(spec.actions) },
      };
  }
}

/** The downloadable result of a finished stage and its file extension. */
export function stageOutput(stage: Stage, t: MeshyTask): { url: string | undefined; ext: string } {
  if (stage === "concept") return { url: t.image_urls?.[0], ext: "png" };
  if (stage === "model") return { url: t.model_urls?.glb, ext: "glb" };
  if (stage === "rig")
    return { url: t.result?.rigged_character_glb_url as string | undefined, ext: "glb" };
  return { url: t.result?.animation_glb_url as string | undefined, ext: "glb" };
}

/** Next stage to run, or null when done; `stopAfter` ends the run early for inspection. */
export function nextStage(cp: Checkpoint, stopAfter?: Stage): Stage | null {
  for (const s of STAGES) {
    if (cp.tasks[s]?.status !== "SUCCEEDED" || !cp.files[s]) return s;
    if (s === stopAfter) return null;
  }
  return null;
}

/** Forget a stage and everything after it, so the next run starts it again (`--retry`). */
export function retryFrom(cp: Checkpoint, stage: Stage): void {
  for (const s of STAGES.slice(STAGES.indexOf(stage))) {
    delete cp.tasks[s];
    delete cp.files[s];
  }
}

export function isStage(s: string | undefined): s is Stage {
  return (STAGES as string[]).includes(s ?? "");
}

export interface PipelineIO {
  /** Persist the checkpoint (atomically). Called before every network side effect. */
  save(): void;
  /** Fetch a result file. */
  download(url: string): Promise<Uint8Array>;
  /** Write a file into the job folder. */
  write(name: string, bytes: Uint8Array): void;
  log(message: string): void;
}

/**
 * Run (or resume) the stages for one character. An accepted task id is saved before polling
 * and never resubmitted; a submission whose outcome is unknown stops the run instead of
 * paying twice; a failed task is recorded and needs an explicit retry.
 */
export async function runPipeline(
  meshy: Meshy,
  spec: CharacterSpec,
  cp: Checkpoint,
  io: PipelineIO,
  stopAfter?: Stage,
): Promise<void> {
  for (let stage = nextStage(cp, stopAfter); stage; stage = nextStage(cp, stopAfter)) {
    let task = cp.tasks[stage];
    if (task?.status === "FAILED" || task?.status === "CANCELED")
      throw new MeshyError(
        `${stage} task ${task.id} ${task.status}; rerun with --retry ${stage} to try again`,
        500,
        true,
      );
    if (task?.submitting && !task.id)
      throw new MeshyError(
        `${stage}: an earlier submission may have been accepted without its id being saved. ` +
          `Check the Meshy task list; then rerun with --retry ${stage} (may charge again).`,
        500,
        true,
      );
    const { kind, body } = stageRequest(stage, spec, cp);
    if (!task?.id) {
      task = { id: "", submitting: true };
      cp.tasks[stage] = task;
      io.save();
      task.id = await meshy.submit(kind, body);
      delete task.submitting;
      io.save(); // the id is ours now: a crash after this point resumes, never resubmits
      io.log(`${stage}: submitted ${task.id}`);
    }
    let last = -1;
    let done: MeshyTask;
    try {
      done = await meshy.wait(kind, task.id, {
        onProgress: (t) => {
          if (t.progress !== last) io.log(`${stage}: ${t.status} ${t.progress}%`);
          last = t.progress;
        },
      });
    } catch (err) {
      if (err instanceof MeshyError && err.permanent && /FAILED|CANCELED/.test(err.message)) {
        task.status = err.message.includes("CANCELED") ? "CANCELED" : "FAILED";
        io.save();
      }
      throw err;
    }
    task.status = done.status;
    task.credits = done.consumed_credits;
    task.finishedAt = done.finished_at;
    const { url, ext } = stageOutput(stage, done);
    if (!url) throw new MeshyError(`${stage} succeeded without an output file`, 500, true);
    const file = `${stage}.${ext}`;
    io.write(file, await io.download(url));
    if (done.thumbnail_url) {
      try {
        io.write(`${stage}.thumb.png`, await io.download(done.thumbnail_url));
      } catch {
        // previews are a convenience
      }
    }
    cp.files[stage] = file;
    io.save();
    io.log(`${stage}: done (${done.consumed_credits ?? "?"} credits) -> ${file}`);
  }
}
